/* SUSUN PERMINTAAN — bernomor, sempit, dan sadar panjang.
 *
 * Model TIDAK diminta mengembalikan skrip utuh, melainkan TAMBALAN per
 * baris. Alasannya bukan menghemat biaya: jawaban model punya batas
 * token, jadi skrip panjang yang dikembalikan utuh akan TERPOTONG di
 * tengah — dan potongan yang rapi masih terlihat seperti skrip yang sah
 * sampai dijalankan. Tambalan tidak punya mode gagal seperti itu:
 * panjang jawaban ditentukan jumlah galat, bukan panjang skrip.
 *
 * Efek sampingnya justru yang paling berharga: model jadi MUSTAHIL
 * menulis ulang skrip diam-diam, karena yang bisa ia kirim hanya baris
 * yang ia sebut nomornya. */
const b = $input.first().json.body ?? $input.first().json;
const kode = String(b.kode || '');
const galat = Array.isArray(b.galat) ? b.galat.map(String) : [];
const dilewati = Array.isArray(b.dilewati) ? b.dilewati.map(String) : [];
const baris = kode.split('\n');

/* Nomor baris yang disebut mesin Pine di pesan galatnya. */
const nomor = [];
for (const p of [...galat, ...dilewati]) {
  const m = p.match(/baris\s+(\d+)/i);
  if (m) nomor.push(parseInt(m[1], 10));
}

/* Skrip pendek dikirim utuh — konteks penuh selalu lebih baik kalau
 * muat. Skrip panjang dikirim sebagai JENDELA di sekitar tiap baris
 * bermasalah, plus kepala berkas: deklarasi indicator() dan input ada di
 * situ, dan tanpa itu model menebak-nebak tipe variabel. */
const AMBANG = 60000;
let potongan;
let sebagian = false;
if (kode.length <= AMBANG || nomor.length === 0) {
  potongan = baris.map((t, i) => (i + 1) + '| ' + t).join('\n');
} else {
  sebagian = true;
  const perlu = new Set();
  for (let i = 1; i <= Math.min(15, baris.length); i++) perlu.add(i);
  for (const n of nomor) {
    for (let i = Math.max(1, n - 20); i <= Math.min(baris.length, n + 20); i++) perlu.add(i);
  }
  const urut = [...perlu].sort((x, y) => x - y);
  const out = [];
  let akhir = 0;
  for (const n of urut) {
    if (n > akhir + 1) out.push('   ... (' + (n - akhir - 1) + ' baris tidak ditampilkan)');
    out.push(n + '| ' + baris[n - 1]);
    akhir = n;
  }
  if (akhir < baris.length) out.push('   ... (' + (baris.length - akhir) + ' baris tidak ditampilkan)');
  potongan = out.join('\n');
}

const aturan = [
  'Kamu memperbaiki skrip Pine v5/v6 agar bisa dijalankan mesin Pine sederhana milik Jadi Trader Tools.',
  'Kode diberikan BERNOMOR dengan format "12| isi baris". Nomor dan tanda | itu BUKAN bagian dari kode.',
  '',
  'ATURAN YANG TIDAK BOLEH DILANGGAR:',
  '1. Balas hanya TAMBALAN untuk baris yang bermasalah. Jangan mengirim ulang seluruh skrip.',
  '2. Jangan menyentuh baris yang tidak disebut dalam daftar galat, kecuali baris itu memang penyebab langsungnya.',
  '3. Jangan mengubah maksud indikatornya. Kalau sebuah fitur memang tidak didukung, KOMENTARI barisnya (awali //) lalu jelaskan; jangan menggantinya dengan perhitungan lain yang sekadar terlihat mirip.',
  '4. Jangan mengubah deklarasi indicator()/study(), termasuk overlay=.',
  '5. Balas HANYA JSON valid, tanpa pagar kode markdown, dengan bentuk:',
  '   {"perbaikan":[{"baris":82,"jadi":"    plot(x, color=color.red)"}],"penjelasan":"2-4 kalimat","perubahan":["baris 82: ..."]}',
  '',
  'Bentuk tambalan:',
  '- {"baris":N,"jadi":"teks pengganti"} menimpa baris N. Boleh memuat \\n kalau satu baris perlu menjadi beberapa baris.',
  '- {"baris":N,"hapus":true} membuang baris N.',
  'Tulis "jadi" sebagai baris utuh lengkap dengan indentasi aslinya.',
].join('\n');

const permintaan = [
  '## Baris yang DITOLAK mesin',
  galat.length ? galat.map((g, i) => (i + 1) + '. ' + g).join('\n') : '(tidak ada)',
  '',
  '## Baris yang DILEWATI (belum didukung)',
  dilewati.length ? dilewati.map((g, i) => (i + 1) + '. ' + g).join('\n') : '(tidak ada)',
  '',
  b.catatan ? '## Catatan pengguna\n' + b.catatan + '\n' : '',
  '## Skrip (' + baris.length + ' baris' + (sebagian ? ', ditampilkan sekitar baris bermasalah saja' : '') + ')',
  potongan,
].join('\n');

return [{ json: { aturan, permintaan, kodeAsli: kode, jumlahBaris: baris.length } }];

/* TERAPKAN TAMBALAN — yang menempel mesin, bukan model.
 *
 * Model cuma bilang "baris 82 jadi begini". Yang menyalin, menggeser,
 * dan menyusun ulang berkas adalah kode di bawah ini, yang perilakunya
 * sama persis setiap kali. Karena itu skrip tidak bisa hilang sebagian
 * gara-gara jawaban model terpotong di tengah. */
const raw = $input.first().json;
const asli = $('Susun permintaan').first().json.kodeAsli || '';
const barisAsli = asli.split('\n');

let teks = raw.content ?? raw.text ?? raw.message?.content ?? raw.output ?? '';
if (Array.isArray(teks)) teks = teks.map(x => x.text ?? x).join('');
teks = String(teks).trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let j;
try {
  j = JSON.parse(teks);
} catch (e) {
  const m = teks.match(/\{[\s\S]*\}/);
  if (!m) return [{ json: { error: 'Jawaban agen bukan JSON yang bisa dibaca.' } }];
  try { j = JSON.parse(m[0]); }
  catch (e2) { return [{ json: { error: 'Jawaban agen bukan JSON yang bisa dibaca.' } }]; }
}

const tambalan = Array.isArray(j.perbaikan) ? j.perbaikan : [];
if (!tambalan.length) {
  return [{ json: { error: j.penjelasan ? ('Agen tidak menemukan perbaikan. Katanya: ' + j.penjelasan) : 'Agen tidak mengusulkan perubahan apa pun.' } }];
}
if (tambalan.length > 60) {
  return [{ json: { error: 'Ditolak: agen ingin mengubah ' + tambalan.length + ' baris sekaligus. Itu penulisan ulang, bukan perbaikan.' } }];
}

/* Ditempel dari nomor besar ke kecil, supaya penyisipan tidak menggeser
   nomor baris tambalan berikutnya. */
const hasil = barisAsli.slice();
const diabaikan = [];
for (const t of tambalan.slice().sort((a, z) => Number(z.baris) - Number(a.baris))) {
  const n = Number(t.baris);
  if (!Number.isInteger(n) || n < 1 || n > barisAsli.length) {
    diabaikan.push('baris ' + t.baris + ' di luar jangkauan skrip'); continue;
  }
  if (t.hapus === true) { hasil.splice(n - 1, 1); continue; }
  if (typeof t.jadi !== 'string') {
    diabaikan.push('baris ' + n + ' dikirim tanpa teks pengganti'); continue;
  }
  hasil.splice(n - 1, 1, ...String(t.jadi).split('\n'));
}
const kode = hasil.join('\n');

/* Pagar terakhir: baris indicator() tidak boleh berubah. overlay= yang
   bergeser memindahkan indikator ke panel lain — perubahan yang tidak
   diminta, dan paling membingungkan saat tiba-tiba muncul. */
const dekl = (s) => { const m = s.match(/(?:indicator|study)\s*\([^\n]*\)/i); return m ? m[0] : ''; };
if (dekl(asli) !== dekl(kode)) {
  return [{ json: { error: 'Ditolak: agen menyentuh baris indicator(). Deklarasi indikator tidak boleh diubah.' } }];
}

const perubahan = Array.isArray(j.perubahan) ? j.perubahan.map(String) : [];
for (const d of diabaikan) perubahan.push('DIABAIKAN — ' + d);

return [{ json: { kode, penjelasan: String(j.penjelasan || ''), perubahan } }];
